### The Wireless Command Center Sketch

This sketch parses single-character steering and diagnostic commands over Bluetooth, toggles the onboard Pin 13 LED to simulate motor activation, and dispatches formatted telemetry responses back to your phone.

```cpp
// Monster Lab - Smartphone Wireless Command Center
#include <SoftwareSerial.h>

// Pin 10 = RX, Pin 11 = TX (via voltage divider)
SoftwareSerial bt(10, 11);
const int STATUS_LED = 13;
bool systemActive = false;

void setup() {
  Serial.begin(9600); // USB Debug Console
  bt.begin(9600);     // Wireless Bluetooth Link

  pinMode(STATUS_LED, OUTPUT);
  digitalWrite(STATUS_LED, LOW);

  Serial.println("# WIRELESS COMMAND CENTER ONLINE");
  bt.println("====================================");
  bt.println("ROBOT ONLINE: Send F, S, or ?");
  bt.println("====================================");
}

void loop() {
  // Check if phone sent a wireless command
  if (bt.available()) {
    char cmd = bt.read();

    switch (cmd) {
      case 'F':
      case 'f': // Case-insensitive
        systemActive = true;
        digitalWrite(STATUS_LED, HIGH);
        bt.println("ACK: MOTORS_ENGAGED [FORWARD]");
        Serial.println("Command Executed: FORWARD (LED ON)");
        break;

      case 'S':
      case 's':
        systemActive = false;
        digitalWrite(STATUS_LED, LOW);
        bt.println("ACK: MOTORS_HALTED [STOPPED]");
        Serial.println("Command Executed: STOP (LED OFF)");
        break;

      case '?': // Telemetry Query
        bt.print("TELEMETRY: STATE=");
        bt.print(systemActive ? "ACTIVE" : "STANDBY");
        bt.println(", BATT=92%, TEMP=24.2C");
        Serial.println("Telemetry report dispatched to smartphone");
        break;

      case '\r':
      case '\n':
        // Silently ignore terminal line terminator bytes
        break;

      default:
        bt.print("ERR: UNKNOWN_CMD ['");
        bt.print(cmd);
        bt.println("']");
        Serial.print("Ignored invalid byte: ");
        Serial.println((int)cmd);
        break;
    }
  }
}
```

### Code Breakdown:
1. `case 'F': case 'f':`: Handles both upper and lowercase inputs gracefully.
2. `case '\r': case '\n': break;`: Prevents smartphone terminal line feeds from triggering error messages.
3. `bt.println("ACK: ...")`: Immediately confirms execution back to the mobile screen.
